create or replace TABLE KFL_PRODUCTION.DBP_ETL.WUP_DENORM_TMP_1 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Marktnummer aus t001w.werks',
	BED_FLEISCH_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept Fleisch Flag',
	BED_FLEISCH_DAT DATE COMMENT 'Datum, ab dem das aktuelle Bedienkonzept gültig ist',
	BED_WURST_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept Wurst Flag',
	BED_WURST_DAT DATE COMMENT 'Bedienkonzept Wurst Datum',
	BED_GEFL_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept Geflügel Flag',
	BED_GEFL_DAT DATE COMMENT 'Bedienkonzept Geflügel Datum',
	BED_KAESE_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept  Käse Flag',
	BED_KAESE_DAT DATE COMMENT 'Bedienkonzept  Käse Datum',
	BED_FISCH_ID NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept Fisch. ID verweist auf SB, Bedienung oder Bedienung/SB',
	BED_FISCH_DAT DATE COMMENT 'Bedienkonzept Fisch Datum',
	BED_FEINK_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept Feinkost Flag',
	BED_FEINK_DAT DATE COMMENT 'Bedienkonzept Feinkost Datum',
	BED_BULK_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept  Bulkfood Flag',
	BED_BULK_DAT DATE COMMENT 'Bedienkonzept  Bulkfood Datum',
	BED_BEDINS_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept Bedieninsel Flag',
	BED_BEDINS_DAT DATE COMMENT 'Bedienkonzept Bedieninsel Datum',
	BED_IMBISS_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienkonzept Imbiss Flag',
	BED_IMBISS_DAT DATE COMMENT 'Bedienkonzept Imbiss Datum',
	BED_BACKSHOP_FG NUMBER(38,0) NOT NULL COMMENT 'Bedienungskonzept Backshop Flag',
	BED_BACKSHOP_DAT DATE COMMENT 'Bedienungskonzept Backshop Datum',
	BACKSHOP_SYSTEM VARCHAR(40) COLLATE 'en-ci' COMMENT 'Backshop System, z.Bsp. Discount',
	LEERGUT_SYSTEM VARCHAR(40) COLLATE 'en-ci' COMMENT 'Leergut System, z.Bsp. Leergutautomat',
	ANZ_LEERGUTAUTOMATEN NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl der Leergutautomaten',
	GLV_LAND_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID des GLV Land_1',
	STV_GLV_LAND_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID des stellvertretenden GLV Land_1',
	GL_VERTRIEB_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter_id der/des GL Vertrieb',
	GF_GBL_VERTRIEB_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID der/des GF_1/GBL Vertrieb',
	VKL_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID der/des Verkaufsleiters. Achtung: abweichend von der bisher im DWH generierten VKL_1-ID',
	HAUSLEITER_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID des Hausleiters',
	WBL_FOOD_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID der Warenbereichsleitung Food',
	WBL_FRISCHE_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter Id der Warenbereichsleitung Frische',
	WBL_NONFOOD_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID der Warenbereichsleitung Nonfood',
	WBL_KASSE_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID der Warenbereichsleitung Kasse',
	FRISCHE_MANAGER_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID des Frischemanagements',
	REGIONALE_PSB_ID NUMBER(38,0) NOT NULL COMMENT 'Mitarbeiter ID der regionalen Personalsachbearbeitung',
	TANKSTELLE_VORH_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag ist gesetzt, wenn eine_1 Tankstelle vorhanden ist. Kommt aus techn_platz_ebene_2',
	TANKSTELLE_EIGEN_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag, ob eine_1 Tankstelle in Eigenverwendung. 1 = eigen',
	MA_VERMIETUNG_ID NUMBER(38,0) COMMENT 'Mitarbeiter Vermietung. Referenz zur Tabelle l_ma.',
	EIGENTUM_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Eigentum Flag. Wenn = 1, dann Eigentum, 0 = Miete',
	DAT_LETZTE_REORGA DATE COMMENT 'Datum der letzten großen Umbaumaßnahme. Wird aus cpr_cl_punkt_termin_1 ermittelt.',
	PARKHAUS_KZ NUMBER(38,0) NOT NULL COMMENT 'Parkhaus Kennzeichen. Kann die Werte 0= kein Parkhaus, 1 = Parkhaus, -1 = unbekannt annehmen. Die Information wird aus der Spalte betreiberart_bez der Tabelle l_ginfo_betreiberart_1 ermittelt',
	GETRAENKEMARKT_KZ NUMBER(38,0) NOT NULL COMMENT 'Kennzeichen für einen separaten Getränkemarkt. Kann die Werte 0= kein Getränkemarkt. 1 = Getränkemarkt. -1 = unbekannt annehmen. Die Information wird aus der Spalte betreiberart_bez der Tabelle l_ginfo_betreiberart_1 ermittelt',
	ANZ_AUFZUEGE NUMBER(38,0) NOT NULL COMMENT 'Anzahl Aufzüge (gesamt) pro Markt. Wird berechnet aus der IOS-Versorgung (598 VAUS) der EQUI-Schnittstelle.',
	ANZ_ROLLSTEIGE NUMBER(38,0) NOT NULL COMMENT 'Anzahl Rollsteige (gesamt) pro Markt. Wird berechnet aus der IOS-Versorgung (598 VAUS) der EQUI-Schnittstelle.',
	ANZ_AUFZUEGE_INTERN NUMBER(38,0) NOT NULL COMMENT 'Anzahl Aufzüge (nur innerhalb der Verkaufsfläche) pro Markt. Wird berechnet aus der IOS-Versorgung (598 VAUS) der EQUI-Schnittstelle.',
	ANZ_ROLLSTEIGE_INTERN NUMBER(38,0) NOT NULL COMMENT 'Anzahl Rollsteige (nur innerhalb der Verkaufsfläche) pro Markt. Wird berechnet aus der IOS-Versorgung (598 VAUS) der EQUI-Schnittstelle.',
	UNTERVERMIETUNG_KZ VARCHAR(20) COLLATE 'en-ci' COMMENT 'Quelle sind interne Mietverträge(mehrere Angaben zur Filiale möglich) - sonst an keiner Stelle im DWH vorhanden',
	UNTERVERMIETUNG_TEXT VARCHAR(160) COLLATE 'en-ci' COMMENT 'Quelle sind interne Mietverträge(mehrere Angaben zur Filiale möglich) - sonst an keiner Stelle im DWH vorhanden',
	UNTERVERMIETUNG_FREITEXT VARCHAR(160) COLLATE 'en-ci' COMMENT 'Quelle sind interne Mietverträge(mehrere Angaben zur Filiale möglich) - sonst an keiner Stelle im DWH vorhanden',
	HAUSLEITER_SPERR_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag zeigt an, ob TEKU-Berichte für den Hausleiter gesperrt sind (1 = gesperrt)',
	VKL_SPERR_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag zeigt an, ob TEKU-Berichte für den VKL_1 gesperrt sind (1 = gesperrt)',
	GF_GBL_VERTRIEB_SPERR_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag zeigt an, ob TEKU-Berichte für den GF_1 gesperrt sind (1 = gesperrt)',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	ANZ_EINKAUFSWAGEN_BOXEN NUMBER(38,0) COMMENT 'Anzahl der Einkaufswagen Boxen. Wird manuell von VT INT erhoben.',
	ANZ_HEISSGETRAENKE_AUTOMATEN NUMBER(38,0) COMMENT 'Anzahl der Heißgetränkeautomaten. Wird manuell von VT INT erhoben.',
	ANZ_T_ZELLEN_BACKSHOP NUMBER(38,0) COMMENT 'Anzahl der Tiefkühlplätze beim Backshop. Wird manuell von VT INT erhoben.',
	HAEUFIGSTE_ULTRA_FRISCHE_LISTUNGSSTUFE_KZ VARCHAR(50) COMMENT 'Gibt die häufigste Listungsstufe der SOK Abteilung Ultra Frische in der Filiale an.',
	HAEUFIGSTE_MOPRO_LISTUNGSSTUFE_KZ VARCHAR(50) COMMENT 'Gibt die häufigste Listungsstufe des SOK Fima Bausteins Mopro in der FIliale an.',
	HAEUFIGSTE_TIKO_LISTUNGSSTUFE_KZ VARCHAR(50) COMMENT 'Gibt die häufigste Listungsstufe des SOK Fima Bausteins Tiko in der Filiale an.',
	HAEUFIGSTE_TROCKEN_LISTUNGSSTUFE_KZ VARCHAR(50) COMMENT 'Gibt die häufigste Listungsstufe der SOK Kategorie Trockenachsen Food in der Filiale an.',
	HAEUFIGSTE_NONFOOD_LISTUNGSSTUFE_KZ VARCHAR(50) COMMENT 'Gibt die häufigste Listungsstufe der Food / Non Food Kategorie Non Food in der Filiale an.',
	constraint PK_WUP_DENORM primary key (MANDANT_ID, WUP_ID)
);